      "description": ""
    },
    {
      "name": "律师事务所负责人",
      "value": "lawFirmDirector",
      "type": "single",
      "description": ""
    },
    {
      "name": "经办律师2",
      "value": "handlingAttorney2",
      "type": "single",
      "description": "多律师协作"
    },
    {
